package com.project7.localmanager;
import android.content.*;import android.content.res.*;import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;
/** Runs once with frozen194 binaries as oracle, then with current source classes.
 * Synthetic pending only. UUID identity is nondeterministic grant output, normalized;
 * all selected leaves/entropy/policies/ledgers/counters/frames otherwise compared. */
public final class DynamicUpgradeHost {
 static Object normalize(Object v){if(v instanceof String)return((String)v).matches("[0-9a-fA-F]{24}")?"<generated-uuid>":v;if(v instanceof Map){Map<String,Object>r=new TreeMap<>();for(Object key:((Map<?,?>)v).keySet())r.put(String.valueOf(normalize(key)),String.valueOf(key).equals("ctt")&&((Map<?,?>)v).containsKey("u")&&((Map<?,?>)v).containsKey("i")?"<stock-grant-created-at>":normalize(((Map<?,?>)v).get(key)));return r;}if(v instanceof List){List<Object>r=new ArrayList<>();for(Object x:(List<?>)v)r.add(normalize(x));return r;}return v;}
 static Object bson(byte[]bytes){return normalize(BsonLite.messagePackValue(bytes,false));}
 static Map<String,Object> outcome(LocalResourceEngine.Result result){Map<String,Object>m=new LinkedHashMap<>();m.put("profile",bson(result.profile));List<Object>replies=new ArrayList<>();for(LocalResourceEngine.Reply r:result.replies)replies.add(Arrays.asList(r.method,bson(r.parameters)));m.put("replies",replies);return m;}
 static Object canonical(Object v){return normalize(new JSONObject(Collections.singletonMap("value",v)).toMap());}
 static String diff(Object a,Object b,String path){if(a instanceof Map&&b instanceof Map){Map<?,?>x=(Map<?,?>)a,y=(Map<?,?>)b;if(!x.keySet().equals(y.keySet()))return path+" keys "+x.keySet()+" / "+y.keySet();for(Object k:x.keySet()){String d=diff(x.get(k),y.get(k),path+"."+k);if(d!=null)return d;}return null;}if(a instanceof List&&b instanceof List){List<?>x=(List<?>)a,y=(List<?>)b;if(x.size()!=y.size())return path+" size "+x.size()+" / "+y.size();for(int i=0;i<x.size();i++){String d=diff(x.get(i),y.get(i),path+"["+i+"]");if(d!=null)return d;}return null;}if(a instanceof Number&&b instanceof Number&&((Number)a).doubleValue()==((Number)b).doubleValue())return null;return Objects.equals(a,b)?null:path+" "+a+" / "+b;}
 static void same(Object a,Object b,String message){String why=diff(canonical(a),canonical(b),"root");if(why!=null)throw new AssertionError(message+": "+why);}
 public static void main(String[]args)throws Exception{
  Path root=Files.createTempDirectory("dynamic485-upgrade-");try{
   Context context=new Context(root.toFile(),new AssetManager(new File(args[0]),new File(args[1]),new File(args[2]),new File(args[3]),new File(args[4])));CoreDrawPolicy.prepare(context);HistoryDrawPolicy.prepare(context);try(InputStream in=new FileInputStream(args[5])){SelectorPolicy.prepareStream(in);}try(InputStream in=new FileInputStream(args[6])){DynamicDrawPolicy.prepareStream(in);}LocalResourceCatalog catalog;try(InputStream in=new FileInputStream(args[1])){catalog=new LocalResourceCatalog(in);}LocalProfileStore store=new LocalProfileStore(context);Path profiles=root.resolve("profiles");Files.createDirectories(profiles);String user="upgrade485";Path file=profiles.resolve(user+".bson");Path fixture=Paths.get(args[8]);boolean oracle=args[7].equals("oracle");
   if(oracle){Map<String,Object>all=new LinkedHashMap<>();Files.write(file,DynamicEngineHost.seed());LocalResourceEngine.Result group=store.updateResources(user,"requestLuckyDrawFile",BsonLite.document("t",485));byte[]empty=group.profile;LocalResourceEngine.Result first=store.updateResources(user,"requestLuckyDrawCard",BsonLite.document("t",485,"idx",0));byte[]partial=first.profile;
    for(String name:Arrays.asList("empty","partial")){byte[]p=name.equals("empty")?empty:partial;Map<String,Object>caseData=new LinkedHashMap<>();caseData.put("before",Base64.getEncoder().encodeToString(p));Files.write(file,p);caseData.put("resume",outcome(store.updateResources(user,"requestFile",BsonLite.document("t",485))));if(name.equals("partial"))caseData.put("repeat",outcome(store.updateResources(user,"requestLuckyDrawCard",BsonLite.document("t",485,"idx",0))));caseData.put("all",outcome(store.updateResources(user,"requestLuckyDrawAllLeftCard",BsonLite.document("t",485))));all.put(name,caseData);}
    Files.write(fixture,new JSONObject(all).toString(2).getBytes("UTF-8"));System.out.println("DYNAMIC_485_OLD_ORACLE_WRITTEN");
   }else{JSONObject all=new JSONObject(new String(Files.readAllBytes(fixture),"UTF-8"));for(String name:Arrays.asList("empty","partial")){JSONObject data=all.getJSONObject(name);Files.write(file,Base64.getDecoder().decode(data.getString("before")));same(data.getJSONObject("resume").toMap(),outcome(store.updateResources(user,"requestFile",BsonLite.document("t",485))),"old pending resume changed "+name);if(!Arrays.equals(BsonLite.documentValue(LocalDrawEngine.state(Base64.getDecoder().decode(data.getString("before")),485),"q7File"),BsonLite.documentValue(LocalDrawEngine.state(Files.readAllBytes(file),485),"q7File")))throw new AssertionError("old resume changed pending file");if(name.equals("partial"))same(data.getJSONObject("repeat").toMap(),outcome(store.updateResources(user,"requestLuckyDrawCard",BsonLite.document("t",485,"idx",0))),"old revealed repeat changed");if(!Arrays.equals(BsonLite.documentValue(LocalDrawEngine.state(Base64.getDecoder().decode(data.getString("before")),485),"q7File"),BsonLite.documentValue(LocalDrawEngine.state(Files.readAllBytes(file),485),"q7File")))throw new AssertionError("old revealed repeat changed pending file");same(data.getJSONObject("all").toMap(),outcome(store.updateResources(user,"requestLuckyDrawAllLeftCard",BsonLite.document("t",485))),"old pending resolver/ledger changed "+name);}System.out.println("DYNAMIC_485_UPGRADE_COMPAT_PASS old194->current empty+partial, resume/repeat/all; only generated UUID values and original grant-created timestamps normalized");}
  }finally{try(java.util.stream.Stream<Path>s=Files.walk(root)){s.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(IOException e){throw new RuntimeException(e);}});}}
 }
}
